        look(c,Vec3.atCenterOf(PLACE).add(0,.499,0));c.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(PLACE),250);verifyHands(c,true);c.getInput().pressKey(options->options.keyUse);
        await(c,w,level->LoadedLevelAccess.blockState(level,PLACE.above()).is(Blocks.COBBLESTONE)&&actual(level).getInventory().getItem(3).getCount()==6&&actual(level).getOffhandItem().getDamageValue()==1,220,"Real extended block placement did not spend one original cobblestone and exactly one grip charge");
        screenshot(c,"create-vulkan-equipment-source-offhand-extendo-carries-real-block-and-pays-distant-placement");
        select(c,w,InputConstants.KEY_3,2);stand(c,w,55028.5,8.5);var target=c.computeOnClient(client->{var entity=find(client,ids.get().pig);if(entity==null)throw new AssertionError("Actual original long-reach target was never tracked");return entity.getBoundingBox().getCenter();});look(c,target);
        c.waitFor(client->client.hitResult instanceof EntityHitResult hit&&hit.getEntity().getUUID().equals(ids.get().pig),250);c.getInput().pressKey(options->options.keyAttack);
        await(c,w,level->level.getEntity(ids.get().pig) instanceof net.minecraft.world.entity.animal.pig.Pig pig&&pig.getHealth()<pig.getMaxHealth()&&actual(level).getInventory().getItem(2).getDamageValue()==1&&actual(level).getOffhandItem().getDamageValue()==1,220,"Actual dual-grip native attack failed beyond vanilla's accepted range or debited the wrong original grip");
