        c.waitFor(client->find(client,ids.get().golem)!=null,250);var golem=c.computeOnClient(client->find(client,ids.get().golem).getBoundingBox().getCenter());look(c,golem);c.getInput().pressKey(options->options.keyUse);
        var projectileId=new AtomicReference<UUID>();var previous=new AtomicReference<PotatoProjectileEntity>();
        await(c,w,level->{var found=level.getEntitiesOfClass(PotatoProjectileEntity.class,new AABB(STICKY).inflate(8),entity->entity.getItem().is(Items.CAKE)&&entity.getStuckEntity()!=null&&entity.getStuckEntity().getUUID().equals(ids.get().golem));if(found.size()!=1)return false;var shot=found.getFirst();if(actual(level).getOffhandItem().isEmpty()&&actual(level).getInventory().getItem(0).getDamageValue()==2&&actual(level).getInventory().getItem(9).getCount()==6){projectileId.set(shot.getUUID());previous.set(shot);return true;}return false;},220,"Actual physical cake shot did not stick to the original genuine target with one finite charge");
        c.waitFor(client->find(client,projectileId.get()) instanceof PotatoProjectileEntity shot&&shot.getStuckEntity()!=null,200);verifyProjectile(c,projectileId.get());screenshot(c,"create-vulkan-equipment-paid-native-cake-projectile-sticks-to-original-real-target");
        server.runCommand("save-all flush");server.runCommand("gamemode spectator @p");server.runCommand("tp @p 56400.5 15 16.5");await(c,w,level->level.getChunkSource().getChunkNow(STICKY.getX()>>4,STICKY.getZ()>>4)==null,850,"Actual source equipment chunk never physically unloaded after save and travel");
        server.runCommand("tp @p 55044.5 10 10.5");await(c,w,level->level.getEntity(projectileId.get()) instanceof PotatoProjectileEntity shot&&shot!=previous.get()&&shot.getOwner()==actual(level)&&shot.getStuckEntity()!=null&&shot.getStuckEntity().getUUID().equals(ids.get().golem),650,"Fresh native save/load failed to restore original sticky projectile UUID and actual original target custody");
        stand(c,w,55044.5,10.5);c.waitFor(client->find(client,projectileId.get()) instanceof PotatoProjectileEntity shot&&shot.getStuckEntity()!=null,250);verifyProjectile(c,projectileId.get());
        server.runOnServer(ignored->{var level=w.getConnection().getServerLevel();var p=actual(level);if(p.getInventory().getItem(0).getDamageValue()!=2||p.getInventory().getItem(1).getDamageValue()!=1||p.getInventory().getItem(2).getDamageValue()!=1||p.getInventory().getItem(3).getCount()!=6||!p.getInventory().getItem(4).isEmpty()||p.getInventory().getItem(9).getCount()!=6)throw new AssertionError("Actual native save/unload lost original finite source tool/ammo/block receipts");});
        var restoredTarget=c.computeOnClient(client->find(client,ids.get().golem).getBoundingBox().getCenter());look(c,restoredTarget);screenshot(c,"create-vulkan-equipment-fresh-native-owner-restores-original-sticky-entity-and-finite-stock-receipts");
        c.runOnClient(client->client.options.setCameraType(CameraType.THIRD_PERSON_FRONT));c.waitTicks(5);c.runOnClient(client->{var renderer=(net.minecraft.client.renderer.entity.player.AvatarRenderer<net.minecraft.client.player.LocalPlayer>)(Object)client.getEntityRenderDispatcher().getRenderer(client.player);var state=renderer.createRenderState();renderer.extractRenderState(client.player,state,.5f);if(state.getArmPose(client.player.getMainArm())!=net.minecraft.client.model.HumanoidModel.ArmPose.CROSSBOW_HOLD||state.getMainHandItemState().isEmpty())throw new AssertionError("Native third-person extraction lost original cannon CROSSBOW_HOLD and actual held item");});screenshot(c,"create-vulkan-equipment-native-third-person-original-cannon-crossbow-arm-pose");server.runCommand("gamemode spectator @p");
