    private static void moveCakeFromReserve(ClientGameTestContext c,TestSingleplayerContext w){
        c.getInput().pressKey(options->options.keyInventory);
        c.waitFor(client->client.gui.screen() instanceof net.minecraft.client.gui.screens.inventory.InventoryScreen&&client.player.getInventory().getItem(10).is(Items.CAKE)&&client.player.getInventory().getItem(4).isEmpty(),200);
        c.runOnClient(client->EquipmentNativeGuiProbe.begin("create-vulkan-equipment-real-paid-inventory-native-gui-atlas-and-bounds"));try{c.takeScreenshot("create-vulkan-equipment-real-paid-inventory-native-gui-atlas-and-bounds");}finally{c.runOnClient(client->EquipmentNativeGuiProbe.end());}
        clickInventorySlot(c,10);c.waitFor(client->client.player.containerMenu.getCarried().is(Items.CAKE)&&client.player.getInventory().getItem(10).isEmpty(),200);
        clickInventorySlot(c,4);c.waitFor(client->client.player.containerMenu.getCarried().isEmpty()&&client.player.getInventory().getItem(4).is(Items.CAKE),200);
        await(c,w,level->{var player=actual(level);return player.containerMenu.getCarried().isEmpty()&&player.getInventory().getItem(10).isEmpty()&&ItemStack.matches(player.getInventory().getItem(4),named(Items.CAKE,1));},200,"Physical native inventory transfer did not retain the one original named cake");
        c.getInput().pressKey(InputConstants.KEY_ESCAPE);c.waitFor(client->client.gui.screen()==null,200);
    }
    private static void clickInventorySlot(ClientGameTestContext c,int inventoryIndex){
        var point=c.computeOnClient(client->{var screen=(net.minecraft.client.gui.screens.inventory.InventoryScreen)client.gui.screen();var origin=(com.simibubi.create.test.mixin.NativeContainerScreenAccessor)screen;var slot=screen.getMenu().slots.stream().filter(candidate->candidate.container==client.player.getInventory()&&candidate.getContainerSlot()==inventoryIndex).findFirst().orElseThrow();float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2((origin.create$getLeft()+slot.x+8)*scaleX,(origin.create$getTop()+slot.y+8)*scaleY);});
        c.getInput().setCursorPos(point.x,point.y);c.waitTicks(2);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);
    }
    /** Observes the real native animation only; never changes heights or renderer state. */
    private static void waitForFullyEquipped(ClientGameTestContext c){c.waitFor(client->{var state=new FirstPersonHandsAndItemsRenderState();client.player.firstPersonHandsAndItems().extractRenderState(client.player,.5f,state);return state.mainHandItem.getItem()==client.player.getMainHandItem().getItem()&&state.mainHandHeight>=.999f&&state.oldMainHandHeight>=.999f&&(state.offHandItem.isEmpty()||state.offHandHeight>=.999f&&state.oldOffHandHeight>=.999f);},250);}
    private static void verifyHands(ClientGameTestContext c,boolean grip){c.waitFor(client->{var state=new FirstPersonHandsAndItemsRenderState();client.player.firstPersonHandsAndItems().extractRenderState(client.player,.5f,state);var hand=((EquipmentHandsAccess)state).create$equipmentHands().main;return state.mainHandItem.getItem()==client.player.getMainHandItem().getItem()&&state.offHandItem.getItem()==client.player.getOffhandItem().getItem()&&hand.custom&&hand.extendo==grip&&hand.item!=null&&!hand.item.isEmpty();},250);c.runOnClient(client->{var state=new FirstPersonHandsAndItemsRenderState();client.player.firstPersonHandsAndItems().extractRenderState(client.player,.5f,state);var equipment=((EquipmentHandsAccess)state).create$equipmentHands();if(!equipment.main.custom||equipment.main.extendo!=grip||equipment.main.item==null||equipment.main.item.isEmpty())throw new AssertionError("Actual native source equipment hand extraction is missing the correct real item");var rendered=grip?ExtendoGripItemRenderer.INSTANCE.extractArgument(new ItemStack(AllItems.EXTENDO_GRIP)):PotatoCannonItemRenderer.INSTANCE.extractArgument(client.player.getMainHandItem());if(rendered.draws.size()!=(grip?9:2)||rendered.draws.stream().anyMatch(draw->draw.quads().isEmpty()||!draw.transform().isFinite()))throw new AssertionError("Actual native equipment extraction lost source animated pieces or finite matrices");});}
    private static void verifyProjectile(ClientGameTestContext c,UUID id){c.runOnClient(client->{var shot=(PotatoProjectileEntity)find(client,id);var renderer=(PotatoProjectileRenderer)client.getEntityRenderDispatcher().getRenderer(shot);var state=renderer.createRenderState();renderer.extractRenderState(shot,state,.5f);if(state.item.isEmpty()||!state.transform.isFinite()||!shot.getItem().getHoverName().equals(Component.literal(NAME)))throw new AssertionError("Native tracked source projectile lost actual item, original components or extracted render transform");});}
    private static Entity find(Minecraft client,UUID id){for(var entity:client.level.entitiesForRendering())if(entity.getUUID().equals(id))return entity;return null;}
    private static ItemStack named(Item item,int count){var stack=new ItemStack(item,count);stack.set(DataComponents.CUSTOM_NAME,Component.literal(NAME));return stack;}
    private static ServerPlayer actual(ServerLevel level){return level.getServer().getPlayerList().getPlayers().getFirst();}
    private static void select(ClientGameTestContext c,TestSingleplayerContext w,int key,int slot){c.getInput().pressKey(key);c.waitFor(client->client.player.getInventory().getSelectedSlot()==slot,200);c.waitFor(client->{var rendered=new FirstPersonHandsAndItemsRenderState();client.player.firstPersonHandsAndItems().extractRenderState(client.player,.5f,rendered);return rendered.mainHandItem.getItem()==client.player.getMainHandItem().getItem();},200);await(c,w,level->actual(level).getInventory().getSelectedSlot()==slot,200,"Native hotbar key did not acknowledge actual selected slot "+slot);}
    private static void stand(ClientGameTestContext c,TestSingleplayerContext w,double x,double z){w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("tp @p "+x+" 5 "+z);c.waitFor(client->client.player.onGround()&&!client.player.isSpectator()&&Math.abs(client.player.getX()-x)<.1&&Math.abs(client.player.getZ()-z)<.1,250);}
    private static void look(ClientGameTestContext c,Vec3 target){var angles=c.computeOnClient(client->{var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});c.getInput().lookAt(angles.x,angles.y);}
    private static void await(ClientGameTestContext c,TestSingleplayerContext w,Predicate<ServerLevel> predicate,int ticks,String failure){var yes=new AtomicBoolean();for(int tick=0;tick<ticks;tick++){w.getServer().runOnServer(ignored->yes.set(predicate.test(w.getConnection().getServerLevel())));if(yes.get())return;c.waitTicks(1);}var diagnostic=new AtomicReference<String>();w.getServer().runOnServer(ignored->{var level=w.getConnection().getServerLevel();var player=actual(level);diagnostic.set("server slot="+player.getInventory().getSelectedSlot()+", main="+player.getMainHandItem()+", damage="+player.getInventory().getItem(0).getDamageValue()+", off="+player.getOffhandItem()+", ammo9="+player.getInventory().getItem(9)+", mode="+player.gameMode()+", using="+player.isUsingItem()+", position="+player.position()+", nearbyShots="+level.getEntitiesOfClass(PotatoProjectileEntity.class,player.getBoundingBox().inflate(32)).size());});var clientState=c.computeOnClient(client->"client slot="+client.player.getInventory().getSelectedSlot()+", main="+client.player.getMainHandItem()+", off="+client.player.getOffhandItem()+", ammo9="+client.player.getInventory().getItem(9)+", modeSpectator="+client.player.isSpectator()+", using="+client.player.isUsingItem()+", screen="+client.gui.screen()+", hit="+client.hitResult);throw new AssertionError(failure+"; "+diagnostic.get()+"; "+clientState);}
    private static void screenshot(ClientGameTestContext c,String name){c.waitFor(client->client.gui.overlay()==null,250);c.runOnClient(client->client.gui.hud.getChat().clearMessages(false));c.runOnClient(client->EquipmentNativeFrameProbe.begin(name));try{c.takeScreenshot(name);}finally{c.runOnClient(client->EquipmentNativeFrameProbe.end());}}
